#!/usr/bin/env python3
"""Check the actual builtins.rs generated by Firefox's trust-anchors crate.

Usage:
  python verify_generated_builtins.py /path/to/out/builtins.rs --report report.json

Validates the three custom labels, linked DER bytes and SHA-256 fields, TLS and
email trust, and Mozilla-policy flag. Produces JSON and exits nonzero on failure.
"""

import argparse
import hashlib
import json
from pathlib import Path
import re

from inject_certificates import SPECS


def parse_hex_bytes(value):
    tokens = [token.strip() for token in value.strip().split(",")]
    if tokens and not tokens[-1]:
        tokens.pop()
    if not tokens or any(not re.fullmatch(r"0x[0-9a-fA-F]{2}", token) for token in tokens):
        raise ValueError("Unexpected byte-array format in generated Rust")
    return bytes(int(token, 16) for token in tokens)


def unique_match(pattern, source, description):
    matches = re.findall(pattern, source, flags=re.DOTALL)
    if len(matches) != 1:
        raise ValueError(f"Expected exactly one {description}; found {len(matches)}")
    return matches[0]


def verify(path):
    raw = path.read_bytes()
    text = raw.decode("utf-8")
    if re.search(r"(?m)^\s*(?:std::)?compile_error!\s*\(", text):
        raise ValueError("Generated Rust contains compile_error!")
    count, body = unique_match(
        r"\bpub\s+static\s+BUILTINS\s*:\s*\[\s*Root\s*;\s*(\d+)\s*\]"
        r"\s*=\s*\[(.*?)\]\s*;\s*$", text, "BUILTINS table")
    entries = re.findall(r"\bRoot\s*\{(.*?)\}\s*,", body, flags=re.DOTALL)
    if len(entries) != int(count):
        raise ValueError(f"BUILTINS table declares {count} entries but contains {len(entries)}")
    checked = []
    for filename, label, anchor, expected_sha256 in SPECS:
        label_pattern = r'\blabel\s*:\s*"' + re.escape(label + r"\0") + r'"\s*,'
        matches = [entry for entry in entries if re.search(label_pattern, entry)]
        if len(matches) != 1:
            raise ValueError(f"Expected one NUL-terminated label {label!r}; found {len(matches)}")
        entry = matches[0]
        server = unique_match(r"\btrust_server\s*:\s*(\w+)\s*,", entry, f"TLS trust for {label}")
        email = unique_match(r"\btrust_email\s*:\s*(\w+)\s*,", entry, f"email trust for {label}")
        expected_server = "CKT_TRUST_ANCHOR_BYTES" if anchor else "CKT_TRUST_MUST_VERIFY_TRUST_BYTES"
        if server != expected_server or email != "CKT_TRUST_MUST_VERIFY_TRUST_BYTES":
            raise ValueError(f"Incorrect trust for {label}: server={server}, email={email}")
        policy = unique_match(r"\bmozilla_ca_policy\s*:\s*(Some\(\s*\w+\s*\)|None)\s*,",
                              entry, f"Mozilla policy for {label}")
        if re.sub(r"\s", "", policy) != "Some(CK_FALSE_BYTES)":
            raise ValueError(f"Unexpected Mozilla-policy flag for custom certificate {label}: {policy}")
        der_ref = unique_match(r"\bder_cert\s*:\s*(ROOT_\d+)\s*,", entry, f"DER reference for {label}")
        der_text = unique_match(
            r"\bstatic\s+" + re.escape(der_ref) + r"\s*:\s*&\s*\[\s*u8\s*\]"
            r"\s*=\s*&\s*\[([^\]]*)\]\s*;", text, f"{der_ref} certificate array")
        der = parse_hex_bytes(der_text)
        actual_sha256 = hashlib.sha256(der).hexdigest()
        if actual_sha256 != expected_sha256:
            raise ValueError(f"Certificate DER hash mismatch for {label}: {actual_sha256}")
        hash_text = unique_match(r"\bsha256\s*:\s*\[([^\]]*)\]\s*,", entry, f"SHA-256 field for {label}")
        if parse_hex_bytes(hash_text).hex() != expected_sha256:
            raise ValueError(f"Generated SHA-256 field mismatch for {label}")
        checked.append({
            "source_certificate": filename,
            "label": label,
            "nul_terminated_label": True,
            "der_reference": der_ref,
            "der_bytes": len(der),
            "sha256_der": actual_sha256,
            "trust_server": server,
            "trust_email": email,
            "tls_trust_anchor": anchor,
            "mozilla_ca_policy": False,
        })
    return {
        "status": "passed",
        "builtins_rs": str(path),
        "builtins_rs_sha256": hashlib.sha256(raw).hexdigest(),
        "builtin_entry_count": int(count),
        "certificates": checked,
        "scope": "Actual generated Rust root-store data; APK inclusion, module loading and live TLS behavior require separate verification.",
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("builtins_rs", type=Path)
    parser.add_argument("--report", type=Path)
    args = parser.parse_args()
    try:
        result = verify(args.builtins_rs)
    except (ValueError, OSError, UnicodeError) as exc:
        result = {"status": "failed", "builtins_rs": str(args.builtins_rs), "error": str(exc)}
    encoded = json.dumps(result, ensure_ascii=False, indent=2) + "\n"
    if args.report:
        args.report.parent.mkdir(parents=True, exist_ok=True)
        args.report.write_text(encoded, encoding="utf-8")
    print(encoded, end="")
    return 0 if result["status"] == "passed" else 1


if __name__ == "__main__":
    raise SystemExit(main())
